INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('MULTI_USER', 'মাল্টি ইউজার', 'Multi User', 'একাধিক ব্যবহারকারী, রোল ও অনুমতি। বন্ধ থাকলে শুধু মালিক ব্যবসায় প্রবেশ করতে পারবেন; অন্য ব্যবহারকারীর তথ্য মুছে যাবে না।', 'Several users with roles and permissions. When off, only the owner can open the business; other users are kept, not deleted.', '👥', 'FREE', 'AVAILABLE', true, 0, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
