INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('ADVANCED_INVENTORY', 'অ্যাডভান্সড ইনভেন্টরি', 'Advanced Inventory', 'স্টক জার্নাল (ঘাটতি/উদ্বৃত্ত সমন্বয়), ক্যাটাগরি ও ব্র্যান্ড ব্যবস্থাপনা। সাধারণ পণ্য, ইউনিট ও স্টক সবসময় চালু।', 'Stock journal (shortage / surplus adjustments), categories and brands. Basic products, units and stock stay on.', '📦', 'PAID', 'AVAILABLE', true, 20, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
