INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('ADVANCED_CUSTOMER', 'অ্যাডভান্সড কাস্টমার ম্যানেজমেন্ট', 'Advanced Customer Management', 'বাকি ও আদায় ড্যাশবোর্ড, মেয়াদোত্তীর্ণ বকেয়া (এজিং), কাস্টমার বাকি রিপোর্ট ও কাস্টমার রিপোর্ট।', 'Dues & collection dashboard, overdue ageing, customer dues and customer summary reports.', '🤝', 'PAID', 'AVAILABLE', true, 30, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
