INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('HRM', 'এইচআরএম (বেতন ও হাজিরা)', 'HRM (Payroll & Attendance)', 'কর্মচারী, বেতন কাঠামো, হাজিরা, ওভারটাইম, মাসিক বেতন, পে-স্লিপ, বেতন পরিশোধ ও অগ্রিম — সরাসরি হিসাবের খাতায় পোস্ট হয়।', 'Employees, salary structures, attendance, overtime, monthly payroll, payslips, salary payments and advances — posted to the books.', '🧑‍💼', 'PAID', 'AVAILABLE', true, 40, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
