INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('DAMAGE_STOCK', 'ড্যামেজ স্টক ইনভেন্টরি', 'Damage Stock Inventory', 'নষ্ট/ক্ষতিগ্রস্ত পণ্য আলাদা স্টকে রাখা, কারণসহ এন্ট্রি, সরবরাহকারীকে ফেরত ও ক্ষতির হিসাব।', 'Keep damaged goods in a separate stock with reasons, return them to suppliers and account for the loss.', '🧯', 'PAID', 'COMING_SOON', false, 50, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
