INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('PRODUCT_EXPIRY', 'পণ্যের মেয়াদ ব্যবস্থাপনা', 'Product Expiry Management', 'ব্যাচভিত্তিক মেয়াদ, মেয়াদোত্তীর্ণ ও শীঘ্রই মেয়াদ শেষের সতর্কবার্তা, FEFO, মেয়াদ রিপোর্ট ও মেয়াদোত্তীর্ণ স্টক বাতিল। বন্ধ থাকলেও ব্যাচের তথ্য সংরক্ষিত থাকে।', 'Batch-level expiry, expired / expiring alerts, FEFO, expiry reports and expired-stock write-off. Batch data is kept while off.', '⏳', 'FREE', 'AVAILABLE', true, 60, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
