INSERT INTO "Feature" ("key", "nameBn", "nameEn", "descriptionBn", "descriptionEn", "icon", "tier", "status", "defaultEnabled", "sortOrder", "updatedAt") VALUES ('PRODUCTION', 'প্রোডাকশন ম্যানেজমেন্ট', 'Production Management', 'কাঁচামাল থেকে তৈরি পণ্য: রেসিপি (BOM), উৎপাদন এন্ট্রি, কাঁচামাল খরচ ও উৎপাদন ব্যয়।', 'Raw materials to finished goods: recipes (BOM), production entries, material consumption and production cost.', '🏭', 'PAID', 'COMING_SOON', false, 70, CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
